// Read-only byte stream from a *flat* cartridge save address space.
// Not wired into core_top yet. The caller must provide exclusive bus ownership.
// FLASH bank switching and EEPROM are deliberately out of scope.
// No cartridge write request is generated by this module.
`default_nettype none
module cart_save_backup_reader (
    input  wire        clk,
    input  wire        reset_n,
    input  wire        start,
    input  wire        exclusive_grant,
    input  wire [16:0] byte_count,
    output reg         save_req,
    output wire [16:0] save_addr,
    output wire        save_rnw,
    input  wire [7:0]  save_dout,
    input  wire        save_done,
    output reg         byte_valid,
    output reg [16:0]  byte_offset,
    output reg [7:0]   byte_data,
    output reg         busy,
    output reg         done,
    output reg         error
);
    localparam [1:0] IDLE=0, ISSUE=1, WAIT_ACK=2;
    reg [1:0] state;
    reg [16:0] offset;
    assign save_addr = offset;
    assign save_rnw = 1'b1;
    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            state <= IDLE;
            offset <= 0;
            save_req <= 0;
            byte_valid <= 0;
            byte_offset <= 0;
            byte_data <= 0;
            busy <= 0;
            done <= 0;
            error <= 0;
        end else begin
            save_req <= 0;
            byte_valid <= 0;
            done <= 0;
            case (state)
                IDLE: if (start) begin
                    error <= 0;
                    offset <= 0;
                    if (!exclusive_grant || byte_count == 0) begin
                        error <= 1;
                        done <= 1;
                    end else begin
                        busy <= 1;
                        state <= ISSUE;
                    end
                end
                ISSUE: begin
                    if (!exclusive_grant) begin
                        error <= 1;
                        busy <= 0;
                        done <= 1;
                        state <= IDLE;
                    end else begin
                        save_req <= 1;
                        state <= WAIT_ACK;
                    end
                end
                WAIT_ACK: begin
                    if (!exclusive_grant) begin
                        error <= 1;
                        busy <= 0;
                        done <= 1;
                        state <= IDLE;
                    end else if (save_done) begin
                        byte_offset <= offset;
                        byte_data <= save_dout;
                        byte_valid <= 1;
                        if (offset == byte_count - 1'b1) begin
                            busy <= 0;
                            done <= 1;
                            state <= IDLE;
                        end else begin
                            offset <= offset + 1'b1;
                            state <= ISSUE;
                        end
                    end
                end
                default: state <= IDLE;
            endcase
        end
    end
endmodule
`default_nettype wire
